// --- LLM-generated --- //
//! Instantiates the floating-point vector types of `ptx_std` in kernels, so that the code and the
//! inline PTX they generate can be validated by `ptxas` for several targets. No GPU is needed.
//!
//! Run `examples/vector_ptxas/check.sh [arch...]` from anywhere; it emits the PTX of this crate
//! for each target (default: `sm_80 sm_89 sm_90 sm_100a sm_103a sm_120a`) and assembles it with
//! `ptxas`.
//!
//! - `main.rs`: the container API of every vector type (the kernels are generated by the macros
//!   below, which the other modules may reuse).
//! - `half.rs`: `f16` and `bf16` vectors.
//! - `narrow.rs`: conversions of the narrow formats.
//! - `f32.rs`: `F32Ext`.
//! - `warp.rs`: warp collectives (shuffles, matches and reductions) on the vector types.
//!
//! Every kernel takes the operands as pointers so that nothing is constant-folded. Variants that
//! are only available on some targets are instantiated under the same `cfg`s as in the library.
//! Note that the `f32` module shadows the primitive type in this file, so it is not used here.

#![no_std]
#![feature(abi_ptx, portable_simd)]
#![allow(clippy::missing_safety_doc)]

use ptx_std::*;

/// Instantiates the container API of an `x2` type `$ty` of `$elem`, with raw bits `$bits`.
macro_rules! container_x2 {
    ($name:ident, $ty:ident, $elem:ident, $bits:ty) => {
        #[unsafe(no_mangle)]
        pub unsafe extern "ptx-kernel" fn $name(
            src: *const $ty,
            elem: *const $elem,
            bits_in: *const $bits,
            arr_in: *const [$elem; 2],
            out: *mut [$ty; 5],
            elems_out: *mut [$elem; 2],
            bits_out: *mut $bits,
            arr_out: *mut [$elem; 2],
        ) {
            unsafe {
                let v = *src;
                *bits_out = v.to_bits();
                *arr_out = v.to_array();
                *elems_out = [v.lo(), v.hi()];
                *out = [
                    <$ty>::from_bits(*bits_in),
                    <$ty>::from_array(*arr_in),
                    <$ty>::splat(*elem),
                    <$ty>::new(v.hi(), v.lo()),
                    <$ty>::from(<[$elem; 2]>::from(v)),
                ];
            }
        }
    };
}

/// Instantiates the container API of a wide type `$ty` of `$elem`, with raw bits `$bits`, whose
/// halves are `$half` and whose pairs are `[$x2; $pairs]`.
macro_rules! container_wide {
    ($name:ident, $ty:ident, $elem:ident, $n:literal, $bits:ty, $half:ident, $x2:ident, $pairs:literal) => {
        #[unsafe(no_mangle)]
        pub unsafe extern "ptx-kernel" fn $name(
            src: *const $ty,
            elem: *const $elem,
            bits_in: *const $bits,
            arr_in: *const [$elem; $n],
            out: *mut [$ty; 5],
            halves_out: *mut [$half; 2],
            bits_out: *mut $bits,
            arr_out: *mut [$elem; $n],
        ) {
            unsafe {
                let v = *src;
                *bits_out = v.to_bits();
                *arr_out = v.to_array();
                *halves_out = [v.lo(), v.hi()];
                let mut x2s: [$x2; $pairs] = v.to_x2s();
                x2s.reverse();
                *out = [
                    <$ty>::from_bits(*bits_in),
                    <$ty>::from_array(*arr_in),
                    <$ty>::splat(*elem),
                    <$ty>::new(v.hi(), v.lo()),
                    <$ty>::from_x2s(x2s),
                ];
            }
        }
    };
}

/// Instantiates the container API of all widths of a format.
macro_rules! container_all {
    (
        $elem:ident,
        $x2:ident($b2:ty) $k2:ident,
        $x4:ident($b4:ty) $k4:ident,
        $x8:ident($b8:ty) $k8:ident,
        $x16:ident($b16:ty) $k16:ident,
        $x32:ident($b32:ty) $k32:ident $(,)?
    ) => {
        container_x2!($k2, $x2, $elem, $b2);
        container_wide!($k4, $x4, $elem, 4, $b4, $x2, $x2, 2);
        container_wide!($k8, $x8, $elem, 8, $b8, $x4, $x2, 4);
        container_wide!($k16, $x16, $elem, 16, $b16, $x8, $x2, 8);
        container_wide!($k32, $x32, $elem, 32, $b32, $x16, $x2, 16);
    };
}

